t row: # skip blank lines (csv.reader might return empty lists for empty lines)\n            continue\n        \n        if len(row) != 4: # skip rows that don't have exactly four fields\n            continue\n        \n        # Row: date, category, description, amount\n        category_raw = row[1]\n        amount_raw = row[3]\n        \n        if not amount_raw or not amount_raw.strip():\n            continue\n            \n        # Process category\n        category = category_raw.strip().lower()\n        \n        # Process amount\n        s = amount_raw.strip()\n        sign = 1\n        if s.startswith('(') and s.endswith(')'):\n            s = s[1:-1].strip()\n            sign = -1\n        \n        # Remove currency symbols and thousands separators\n        for char in ['$', '€', '£', ',']:\n            s = s.replace(char, '')\n            \n        try:\n            amount = Decimal(s) * sign\n        except Exception:\n            # If amount is not a valid number, we should probably skip it\n            continue\n            \n        totals[category] = totals.get(category, Decimal('0')) + amount\n        \n    # Round and convert to float\n    result = {}\n    for cat, total in totals.items():\n        rounded = total.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)\n        result[cat] = float(rounded)\n        \n    return result\n```\n\nVerification:\n- Ran `python3 tests/check_ledger.py`\n- Result: `LEDGER_OK`"}}
